inline bool registryKey(const std::string& k){return k=="hongtu:cross_sections:v1"||k=="kfactory:settings:version"||k=="kfactory:settings:meta_format"||k=="kfactory:settings:klayout_version"||k.rfind("kfactory:cross_section:",0)==0||k.rfind("kfactory:asymmetrical_cross_section:",0)==0||k.rfind("kfactory:layer_enclosure:",0)==0;}
inline bool cellKey(const std::string& k){return k=="hongtu:cell_key:v1"||k=="hongtu:ports:v1"||k=="hongtu:cell_lineage:v1"||k.rfind("kfactory:ports:",0)==0;}
