inline Value physicalDefinition(const Value& d){Value v=Value::dict();for(const char* key:{"schemaVersion","kind","widthNm","layerNumber","datatype","sectionMinNm","sectionMaxNm","radiusNm","radiusMinNm"})if(d.get(key).kind!='0')v.set(key,d.get(key));Value e=Value::dict();const auto& enclosure=d.get("enclosure");e.set("bboxSections",enclosure.get("bboxSections").kind=='0'?Value::array():enclosure.get("bboxSections"));if(d.get("kind").kind=='s'&&d.get("kind").text=="asymmetric"){v.set("sections",d.get("sections").kind!='0'?d.get("sections"):enclosure.get("sections"));e.set("sections",Value::array());}else e.set("sections",enclosure.get("sections"));v.set("enclosure",e);return v;}
