        const Value* v=nullptr;int index=sourceIndex(p);if(index>=0){auto found=foreign.find(index);if(found!=foreign.end())v=found->second;}else for(const auto& item:foreign)if(text(item.second->get("name"))==p.name){if(v)throw std::invalid_argument("Ambiguous canonical/KFactory port name");index=item.first;v=item.second;}
