inline std::vector<std::string> Diagnostics(const GdsiiParseResult& d){std::map<std::string,Value> settings;for(const auto& r:d.layoutContextRecords){auto k=safeMetaKey(r);if(k=="kfactory:settings:version"||k=="kfactory:settings:meta_format")addMeta(settings,r);}bool fixed=settings.count("kfactory:settings:version")&&text(settings.at("kfactory:settings:version"))=="3.0.4"&&settings.count("kfactory:settings:meta_format")&&text(settings.at("kfactory:settings:meta_format"))=="v3";std::vector<std::string> out;if(!fixed)for(size_t ci=0;ci<d.cells.size();++ci)for(const auto& r:layout_context::CellRecords(d,ci))if(safeMetaKey(r).rfind("kfactory:ports:",0)==0){out.push_back("Unsupported KFactory metadata version; raw context retained: "+d.cells[ci].name);break;}return out;}
inline void ResolvePortLayers(GdsiiParseResult& d){for(const auto& p:d.ports){auto add=[&](std::vector<LayerInfo>& layers){if(std::none_of(layers.begin(),layers.end(),[&](const LayerInfo& l){return l.layerNumber==p.layerNumber&&l.datatype==p.datatype;}))layers.push_back({p.layerNumber,p.datatype,0});};add(d.allLayers);if(p.ownerCellId>=0&&p.ownerCellId<static_cast<int>(d.cells.size()))add(d.cells[p.ownerCellId].layers);}d.layerCount=static_cast<int>(d.allLayers.size());}
