            Value provenance=Value::dict();provenance.set("kind",Value::str("foreign"));provenance.set("format",Value::str("kfactory"));provenance.set("metaFormat",Value::str("v3"));provenance.set("metaName",Value::str(item.first));provenance.set("portIndex",Value::num(index));provenance.set("ownerCellKey",Value::str(p.ownerCellKey));p.provenance=encode(provenance,true);d.ports.push_back(std::move(p));
