struct ContextPayload {std::vector<std::string> layout;std::vector<std::vector<std::string>> cells;};
inline void replace(std::vector<std::string>& records,const std::string& key,const Value& value){(void)Parser(encode(value,false),false).finish();std::vector<std::string> out;bool done=false;const std::string replacement=metaRecord(key,value);for(const auto& r:records){if(safeMetaKey(r)==key){if(!done){out.push_back(r==replacement?r:replacement);done=true;}}else out.push_back(r);}if(!done)out.push_back(replacement);records=std::move(out);}
